wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(125008644108014240)
,p_name=>'Coberturas_New2'
,p_region_name=>'REPORTE_ASIS'
,p_parent_plug_id=>wwv_flow_imp.id(262381244941822372)
,p_template=>wwv_flow_imp.id(183716147038209674)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'   CASE P.INDPOLCOL',
'    WHEN ''S'' THEN ''COLECTIVA''',
'    WHEN ''N'' THEN ''INDIVIDUAL''',
'    ELSE ''No definido''',
'  END AS TIPO_POLIZA,',
'   P.IDPOLIZA AS CONSECUTIVO,P.NUMPOLUNICO,P.FECINIVIG,P.FECFINVIG,P.STSPOLIZA,',
'   LTRIM(RTRIM((TRANSLATE(OC_CLIENTES.NOMBRE_CLIENTE(P.CODCLIENTE),'',       '',''  '')))) AS CONTRATANTE_POLIZA,  ',
'   CASE CP.TIPO_CLAUSULA',
'  WHEN ''APOY01'' THEN ''FUNERARIO_360''',
'  WHEN ''ASEF01'' THEN ''ASESORIA_FUNERARIA''',
'  WHEN ''ASI-PL'' THEN ''ASISTENCIAS+''',
'  WHEN ''ASI-TH'' THEN ''THONA_ASISTE''',
'  WHEN ''ASI-GM'' THEN ''ASISTENCIAS_GM''',
'  ELSE ''DESCONOCIDO''',
'END AS ASISTENCIA',
',OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ADMINPOL'', P.TipoAdministracion) AS TipoAdministracion,',
'   OC_AGENTES.NOMBRE_AGENTE(1, OC_AGENTE_POLIZA.AGENTE_PRINCIPAL(1, P.IDPOLIZA)) AS NOMBRE_AGENTE,',
'    OC_EJECUTIVO_COMERCIAL.NOMBRE_EJECUTIVO(1,OC_AGENTES.EJECUTIVO_COMERCIAL(1, OC_AGENTE_POLIZA.AGENTE_PRINCIPAL(1, P.IDPOLIZA))) AS NOMBRE_EJECUTIVO',
'        FROM CLAUSULAS_POLIZA CP ',
'        INNER JOIN POLIZAS P ON P.IDPOLIZA=CP.IDPOLIZA',
'        WHERE TIPO_CLAUSULA IN (''ASI-GM'') ',
'        AND(P.IDPOLIZA = :P5_IDPOLIZA',
'        OR P.NUMPOLUNICO = :P5_NUMPOLUNICO);',
' '))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(183758599269209698)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
